{
  "identity": {
    "name": "Ascending IT",
    "location": "Nampa, Idaho",
    "claims": [
      {
        "statement": "Ascending IT maintains its primary office address at 2128 N Devlin Way in Nampa, Idaho.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "2128 N Devlin Way, Nampa, ID 83687"
      },
      {
        "statement": "The company operates in the Treasure Valley and Boise, Idaho regional market.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "With 20+ years of experience, Ascending IT delivers proactive IT management and built-in cybersecurity for small to medium businesses across the Treasure Valley."
      }
    ]
  },
  "industry": {
    "industry": "Managed IT Services & Cybersecurity",
    "activities": [
      "Managed IT Support",
      "Cybersecurity and Threat Protection",
      "Cloud and SaaS Management",
      "Network and Infrastructure Management",
      "Backup and Disaster Recovery",
      "Free IT Assessments"
    ],
    "claims": [
      {
        "statement": "Ascending IT delivers managed IT monitoring, maintenance, and support services to small and medium businesses.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Our Boise Managed IT Services provide 24/7 monitoring, proactive maintenance, and fast support to reduce downtime, control costs, and keep your business running."
      },
      {
        "statement": "Ascending IT provides cybersecurity protection including endpoint protection, ransomware defense, and phishing mitigation.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Defend your Boise business against ransomware, phishing, and data breaches with proactive cybersecurity solutions that protect sensitive data and client trust."
      },
      {
        "statement": "Ascending IT operates as a B2B technology managed service provider rather than a home-service contractor.",
        "label": "inference",
        "sourceUrl": "https://ascending-it.com/boise-it-company/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://ascending-it.com/",
    "claims": [
      {
        "statement": "Ascending IT provides prospective customers with an initial assessment offer directly via its website.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Ready to see where your IT stands today? Start with a Free IT Assessment and get a clear picture of your strengths, risks, and opportunities"
      },
      {
        "statement": "The company maintains web portals for customer payment processing and technical support ticket status tracking.",
        "label": "inference",
        "sourceUrl": "https://ascending-it.com/",
        "quote": null
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "No state contractor licenses, legal entity registration numbers, or corporate registrations are stated on the public pages reviewed.",
        "label": "inference",
        "sourceUrl": "https://ascending-it.com/terms/",
        "quote": null
      }
    ],
    "limitations": "The website does not provide corporate registration numbers, state licensing records, or specific professional certifications."
  },
  "existingSoftware": [
    {
      "product": "ConnectBooster",
      "purpose": "Client payment and billing portal",
      "evidence": {
        "statement": "The website links customer payments to a ConnectBooster portal host (on-sitesvcs.connectboosterportal.com).",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Make A Payment"
      }
    },
    {
      "product": "IT Client Portal",
      "purpose": "Customer support ticket status tracking",
      "evidence": {
        "statement": "The website directs users to an IT client portal host (onsitesvcs.itclientportal.com) to view ticket status.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "View Ticket Status"
      }
    },
    {
      "product": "Fluent Forms",
      "purpose": "Website contact form processing and lead capture",
      "evidence": {
        "statement": "The site loads Fluent Forms script assets to handle form submissions.",
        "label": "inference",
        "sourceUrl": "https://ascending-it.com/it-support-boise/",
        "quote": null
      }
    },
    {
      "product": "WordPress / Divi",
      "purpose": "Content management system and web page styling",
      "evidence": {
        "statement": "The site loads WordPress theme and asset scripts from Divi and DiviFlash directories.",
        "label": "inference",
        "sourceUrl": "https://ascending-it.com/",
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "Ascending IT uses online web forms and direct email/phone contacts to capture IT assessment requests.",
      "label": "fact",
      "sourceUrl": "https://ascending-it.com/it-support-boise/",
      "quote": "Whether you’re ready for your Free IT Assessment or just have a question, we’re here to help."
    },
    {
      "statement": "The company targets commercial business sectors including healthcare, construction, finance, manufacturing, retail, and hospitality.",
      "label": "fact",
      "sourceUrl": "https://ascending-it.com/",
      "quote": "Healthcare Construction Finance & Accounting Professional Services Manufacturing Retail Hospitality"
    }
  ],
  "problems": [
    {
      "problem": "Target market mismatch with ForgeX's service model.",
      "label": "fact",
      "basis": "Ascending IT is a B2B managed service provider and IT consultancy, not an owner-led residential home-service contractor in HVAC, plumbing, or electrical."
    },
    {
      "problem": "Inbound assessment requests may experience manual data entry delays into backend PSA/CRM systems.",
      "label": "hypothesis",
      "basis": "The website relies on basic WordPress Fluent Forms for assessment requests and inquiry routing."
    }
  ],
  "existingSolutions": [
    {
      "solution": "PSA Ticketing and Client Portal Integration (onsitesvcs.itclientportal.com)",
      "addresses": "Client support request tracking and status updates.",
      "alreadyOwned": true
    },
    {
      "solution": "ConnectBooster Payment Integration (on-sitesvcs.connectboosterportal.com)",
      "addresses": "Client invoice payment and billing workflow automation.",
      "alreadyOwned": true
    },
    {
      "solution": "Native Form-to-CRM Webhooks",
      "addresses": "Direct synchronization of Fluent Forms inquiries into backend PSA/ticketing systems.",
      "alreadyOwned": false
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "No ForgeX solutions are recommended because Ascending IT is an IT services provider and falls outside ForgeX's home-services target segment."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "AI delivery evaluation is not applicable as no ForgeX service is recommended."
  },
  "humanReview": [],
  "risks": [
    {
      "type": "operational",
      "description": "Engaging companies outside ForgeX's core home-services contractor focus dilutes sales and delivery specialization."
    },
    {
      "type": "compliance",
      "description": "As a managed service and cybersecurity provider, external workflows would require compliance with strict IT data handling and client confidentiality standards."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": []
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner",
      "President",
      "Founder",
      "Managing Partner"
    ],
    "people": [],
    "channels": [
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://ascending-it.com/"
      },
      {
        "kind": "email",
        "value": "[redacted]",
        "sourceUrl": "https://ascending-it.com/"
      },
      {
        "kind": "web form",
        "value": "https://ascending-it.com/it-support-boise/",
        "sourceUrl": "https://ascending-it.com/it-support-boise/"
      }
    ]
  },
  "discovery": {
    "questions": [
      "What primary PSA or ticketing platform does Ascending IT utilize to process inbound customer leads and support tickets?",
      "Does Ascending IT provide IT support or co-managed services to residential trade contractors in the Boise area?"
    ],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://ascending-it.com/",
        "usedFor": "Company identity, physical location, service tiers, client portal endpoints, and contact details."
      },
      {
        "url": "https://ascending-it.com/boise-it-company/",
        "usedFor": "Company background, operational philosophy, target business types, and core values."
      },
      {
        "url": "https://ascending-it.com/it-support-boise/",
        "usedFor": "Verification of contact form structure, phone number, and physical office address."
      },
      {
        "url": "https://ascending-it.com/terms/",
        "usedFor": "Review of terms, legal disclosures, and embedded external script sources."
      },
      {
        "url": "https://ascending-it.com/privacy-policy/",
        "usedFor": "Review of privacy policy details and business registration indicators."
      },
      {
        "url": "https://ascending-it.com/managed-it-support-boise/",
        "usedFor": "Scope of managed IT services, cybersecurity capabilities, and service package breakdown."
      },
      {
        "url": "https://ascending-it.com/it-blog/",
        "usedFor": "Review of blog publications, author bylines, and technical content."
      },
      {
        "url": "https://ascending-it.com/free-it-assessment-boise/",
        "usedFor": "Assessment intake workflow, assessment scope, and turnaround timeline."
      }
    ],
    "limitations": [
      "The public website does not identify the names or specific roles of company owners, executives, or managers.",
      "Specific pricing figures and monthly contract rates are not published on the website.",
      "State corporate filing numbers and formal legal entity designations are not listed on the public pages."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "Ascending IT is a Managed Service Provider (MSP) offering business IT infrastructure and cybersecurity support. It is outside ForgeX's target segment of owner-led home-service contractors (HVAC, plumbing, and electrical)."
  }
}
